        public static List<dynamic> GetFallbackUsers(DateTime now)
        {
            var list = new List<dynamic>();
            foreach (var u in Items)
            {
                var createdAt = now.AddDays(-u.DaysAgoCreated);
                var lastActive = (DateTime?)now.AddMinutes(-u.MinutesAgoActive);
                bool isOnline = u.MinutesAgoActive <= 3;
                list.Add(new
                {
                    Id = u.Id,
                    Email = u.Email,
                    FullName = u.FullName,
                    AvatarUrl = (string?)null,
                    Role = "User",
                    Gender = u.Gender,
                    SubscriptionType = u.SubscriptionType,
                    CreatedAt = createdAt,
                    TotalUsageSeconds = u.TotalUsageSeconds,
                    LongestSessionSeconds = u.LongestSessionSeconds,
                    PrimaryFeature = u.PrimaryFeature,
                    FeatureUsageJson = u.FeatureUsageJson,
                    LastActiveAt = lastActive,
                    IsOnline = isOnline,
                    TotalClothes = u.TotalClothes,
                    TotalOutfits = u.TotalOutfits
                });
            }
            return list;
        }

        public static async Task SeedRealisticUsersAsync(ApplicationDbContext context, DateTime now)
        {
            try
            {
                var existingEmails = await context.Users
                    .AsNoTracking()
                    .Select(u => u.Email.ToLower())
                    .ToListAsync();
                var emailSet = new HashSet<string>(existingEmails, StringComparer.OrdinalIgnoreCase);

                var passwordHash = BCrypt.Net.BCrypt.HashPassword("123456");
                var toAdd = new List<User>();

                // 1. Đồng bộ và cập nhật email sang định dạng mới không có dấu chấm cho các tài khoản đã tồn tại trong DB
                var allDbUsers = await context.Users.ToListAsync();
                var userByName = allDbUsers
                    .Where(u => !string.IsNullOrWhiteSpace(u.FullName))
                    .GroupBy(u => u.FullName.Trim())
                    .ToDictionary(g => g.Key, g => g.First(), StringComparer.OrdinalIgnoreCase);

                bool hasEmailUpdates = false;
                foreach (var item in Items)
                {
                    if (userByName.TryGetValue(item.FullName.Trim(), out var existingUser))
                    {
                        if (existingUser.Email != item.Email)
                        {
                            Console.WriteLine($"[SeedRealisticUsers]: Cập nhật email User ID {existingUser.Id} ({existingUser.FullName}): '{existingUser.Email}' -> '{item.Email}'");
                            existingUser.Email = item.Email;
                            hasEmailUpdates = true;
                        }
                    }
                }

                if (hasEmailUpdates)
                {
                    await context.SaveChangesAsync();
                    Console.WriteLine("[SeedRealisticUsers]: Đã lưu thành công các email mới không dấu chấm vào Database.");
                    // Cập nhật lại emailSet sau khi đổi email
                    existingEmails = await context.Users.AsNoTracking().Select(u => u.Email.ToLower()).ToListAsync();
                    emailSet = new HashSet<string>(existingEmails, StringComparer.OrdinalIgnoreCase);
                }

                foreach (var item in Items)
                {
                    if (!emailSet.Contains(item.Email))
                    {
                        var user = new User
                        {
                            Email = item.Email,
                            PasswordHash = passwordHash,
                            FullName = item.FullName,
                            Gender = item.Gender,
                            Role = "User",
                            SubscriptionType = item.SubscriptionType,
                            Height = item.Height,
                            Weight = item.Weight,
                            Chest = item.Chest,
                            Waist = item.Waist,
                            Hips = item.Hips,
                            BodyShape = item.BodyShape,
                            Age = item.Age,
                            AgeGroup = item.AgeGroup,
                            TotalUsageSeconds = item.TotalUsageSeconds,
                            LongestSessionSeconds = item.LongestSessionSeconds,
                            PrimaryFeature = item.PrimaryFeature,
                            FeatureUsageJson = item.FeatureUsageJson,
                            LastActiveAt = now.AddMinutes(-item.MinutesAgoActive),
                            CreatedAt = now.AddDays(-item.DaysAgoCreated)
                        };
                        toAdd.Add(user);
                        emailSet.Add(item.Email);
                    }
                }

                if (toAdd.Count > 0)
                {
                    context.Users.AddRange(toAdd);
                    await context.SaveChangesAsync();
                    Console.WriteLine($"[SeedRealisticUsers]: Đã tạo thành công {toAdd.Count} tài khoản người dùng thực tế vào Database.");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"[SeedRealisticUsers Warning]: {ex.Message}");
            }
        }
    }
